<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 설계 과정</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            background-color: #f0f0f0;
        }
        #canvas {
            width: 800px;
            height: 600px;
            border: 1px solid black;
        }
        .info {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: rgba(255, 255, 255, 0.8);
            padding: 10px;
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <div id="canvas"></div>
    <div class="info">
        <h2>롯데월드타워 설계 과정</h2>
        <p>모델 이름: llama4-scout</p>
    </div>

    <script src="../runtime/three-runtime.js"></script>
    <script>
        let scene, camera, renderer, controls;
        let model = null;

        // 도면 정보
        const lotteWorldTower = {
            height: 555, // m
            floorCount: 123,
            baseArea: 3300, // m^2 (가로 60m, 세로 55m)
        };

        // 3D 모델 생성
        function createModel() {
            const geometry = new THREE.BoxGeometry(60, 555, 55);
            const material = new THREE.MeshBasicMaterial({ color: 0xffffff });
            model = new THREE.Mesh(geometry, material);
            scene.add(model);
        }

        // 설계 단계별 3D 모델 생성
        function createDesignModel(stage) {
            let geometry, material;
            switch (stage) {
                case 'initial':
                    geometry = new THREE.BoxGeometry(60, 100, 55);
                    break;
                case 'mid':
                    geometry = new THREE.BoxGeometry(50, 300, 45);
                    break;
                case 'final':
                    geometry = new THREE.BoxGeometry(40, 555, 35);
                    break;
            }
            material = new THREE.MeshBasicMaterial({ color: 0xffffff });
            const mesh = new THREE.Mesh(geometry, material);
            scene.add(mesh);
            return mesh;
        }

        // 초기화
        function init() {
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(75, 800 / 600, 0.1, 1000);
            renderer = new THREE.WebGLRenderer({
                canvas: document.createElement('canvas'),
                antialias: true
            });
            renderer.setSize(800, 600);
            document.getElementById('canvas').appendChild(renderer.domElement);

            controls = new THREE.OrbitControls(camera, renderer.domElement);
            camera.position.z = 500;

            createModel();

            // 설계 단계별 모델
            const initialModel = createDesignModel('initial');
            initialModel.position.y = 50;
            const midModel = createDesignModel('mid');
            midModel.position.y = 300;
            const finalModel = createDesignModel('final');
            finalModel.position.y = 555;

            // 도면 표시
            const drawPlane = new THREE.PlaneGeometry(60, 55);
            const planeMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, opacity: 0.5, transparent: true });
            const plane = new THREE.Mesh(drawPlane, planeMaterial);
            plane.position.y = 0;
            scene.add(plane);

            // 이벤트 핸들러
            document.addEventListener('keydown', (event) => {
                if (event.key === 'r') {
                    camera.position.z = 500;
                    controls.reset();
                }
            });
        }

        // 애니메이션
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        init();
        animate();
    </script>
</body>
</html>
